def piece_side(piece):
    if piece == '.':
        return None
    return 'red' if piece.isupper() else 'black'

def find_general(board, side):
    target = 'K' if side == 'red' else 'k'
    for y, row in enumerate(board):
        for x, piece in enumerate(row):
            if piece == target:
                return (x, y)
    return None

