def rook_targets(board, x, y):
    side = lab.owner(board[y][x])
    result = []
    for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
        nx, ny = x + dx, y + dy
        while lab.inside(nx, ny):
            piece = board[ny][nx]
            if piece == '.':
                result.append((nx, ny))
            else:
                if lab.owner(piece) != side:
                    result.append((nx, ny))
                break
            nx, ny = nx + dx, ny + dy
    return sorted(result)

