def horse_targets(board, x, y):
    side = lab.owner(board[y][x])
    result = []
    for dx,dy in [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(-1,2),(1,-2),(-1,-2)]:
        nx,ny = x+dx,y+dy
        lx = x + (dx//2 if abs(dx)==2 else 0)
        ly = y + (dy//2 if abs(dy)==2 else 0)
        if lab.inside(nx,ny) and board[ly][lx]=='.' and lab.owner(board[ny][nx])!=side:
            result.append((nx,ny))
    return sorted(result)

