def pawn_targets(board, x, y):
    side = lab.owner(board[y][x])
    candidates = [(x,y-1 if side=='red' else y+1)]
    crossed = y<=4 if side=='red' else y>=5
    if crossed:
        candidates += [(x-1,y),(x+1,y)]
    return sorted((nx,ny) for nx,ny in candidates if lab.inside(nx,ny) and lab.owner(board[ny][nx])!=side)

