def is_in_check(board, side):
    king = lab.locate_general(board, side)
    if king is None:
        return True
    for y in range(10):
        for x in range(9):
            if lab.owner(board[y][x]) == lab.opponent(side) and king in lab.targets(board,x,y):
                return True
    return False

