def generate_legal_moves(board, side):
    result = []
    if lab.locate_general(board,side) is None:
        return result
    for move in lab.pseudo_moves(board,side):
        if board[move[3]][move[2]].upper() == 'K':
            continue
        captured = lab.make_move(board,move)
        safe = not lab.in_check(board,side)
        lab.unmake_move(board,move,captured)
        if safe:
            result.append(move)
    return sorted(result)

