def count_material(board):
    score = 0
    for row in board:
        for piece in row:
            if piece != '.':
                value = lab.VALUES[piece.upper()]
                score += value if piece.isupper() else -value
    return score

def soldier_bonus(piece, x, y):
    if piece == 'P':
        return max(0,6-y)*10 + (30 if y<=4 else 0)
    if piece == 'p':
        return -(max(0,y-3)*10 + (30 if y>=5 else 0))
    return 0

