def alpha_beta_score(board, side, depth, alpha, beta):
    leaf = lab.leaf_score(board,side,depth)
    if leaf is not None:
        return leaf
    best = -float('inf') if side=='red' else float('inf')
    for move in lab.legal_moves(board,side):
        captured = lab.make_move(board,move)
        score = alpha_beta_score(board,lab.opponent(side),depth-1,alpha,beta)
        lab.unmake_move(board,move,captured)
        if side=='red':
            best = max(best,score)
            alpha = max(alpha,best)
        else:
            best = min(best,score)
            beta = min(beta,best)
        if alpha >= beta:
            break
    return best

