def search_with_stats(board, side, depth):
    stats = {'nodes':0,'cutoffs':0}
    def visit(turn, remaining, alpha, beta):
        stats['nodes'] += 1
        leaf = lab.leaf_score(board,turn,remaining)
        if leaf is not None:
            return leaf
        best = -float('inf') if turn=='red' else float('inf')
        moves = lab.legal_moves(board,turn)
        for index,move in enumerate(moves):
            captured = lab.make_move(board,move)
            value = visit(lab.opponent(turn),remaining-1,alpha,beta)
            lab.unmake_move(board,move,captured)
            if turn=='red':
                best = max(best,value)
                alpha = max(alpha,best)
            else:
                best = min(best,value)
                beta = min(beta,best)
            if alpha >= beta:
                if index < len(moves)-1:
                    stats['cutoffs'] += 1
                break
        return best
    score = visit(side,depth,-float('inf'),float('inf'))
    return {'score':score,**stats}

