def winning_moves(board, side):
    result = []
    for move in lab.legal_moves(board,side):
        captured = lab.make_move(board,move)
        won = not lab.legal_moves(board,lab.opponent(side))
        lab.unmake_move(board,move,captured)
        if won:
            result.append(move)
    return sorted(result)

import lab

def analyse_endgame(board, side, depth):
    leaf = lab.leaf_score(board,side,depth)
    if leaf is not None:
        return {'move':None,'score':leaf,'line':[]}
    best = {'move':None,'score':-float('inf') if side=='red' else float('inf'),'line':[]}
    for move in sorted(lab.legal_moves(board,side)):
        captured = lab.make_move(board,move)
        child = analyse_endgame(board,lab.opponent(side),depth-1)
        lab.unmake_move(board,move,captured)
        score = child['score']
        if (side=='red' and score>best['score']) or (side=='black' and score<best['score']):
            best = {'move':move,'score':score,'line':[move]+child['line']}
    return best
